const request = $input.first().json || {};
const headers = request.headers || {};
const body = request.body && typeof request.body === 'object' ? request.body : {};
const expected = String(request.n8n_leme_secret || '');
const received = String(headers['x-leme-n8n-key'] || headers['X-LEME-N8N-KEY'] || '');
const safeEqual = (a, b) => {
  if (!a || !b || a.length !== b.length) return false;
  let result = 0;
  for (let i = 0; i < a.length; i++) result |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return result === 0;
};
const required = ['delivery_id', 'client_id', 'start_date', 'end_date'];
const missing = required.filter((key) => !body[key]);
const authorized = safeEqual(received, expected) && missing.length === 0;
return [{ json: {
  ...body,
  _authorized: authorized,
  _auth_error: !safeEqual(received, expected) ? 'X-LEME-N8N-KEY inválida.' : (missing.length ? 'Payload incompleto: ' + missing.join(', ') : ''),
  _source: 'manual',
  n8n_execution_id: String($execution.id)
}, pairedItem: { item: 0 } }];

const response = $input.first().json || {};
const reports = Array.isArray(response.reports) ? response.reports : [];
return reports.map((report, index) => ({
  json: { ...report, _source: 'scheduled', n8n_execution_id: String($execution.id) },
  pairedItem: { item: 0 }
}));

return $input.all().map((item, index) => ({
  json: {
    delivery_id: String(item.json.delivery_id || ''),
    n8n_execution_id: String($execution.id),
    source: item.json._source || item.json.trigger || 'manual'
  },
  pairedItem: { item: index }
})).filter((item) => item.json.delivery_id);

const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[char]));
const number = (value) => new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 0 }).format(Number(value || 0));
const percent = (value) => new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 1 }).format(Number(value || 0)) + '%';
const dateBr = (value) => {
  const parts = String(value || '').slice(0, 10).split('-');
  return parts.length === 3 ? parts.reverse().join('/') : String(value || '');
};
const slug = (value) => String(value || 'cliente')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '') || 'cliente';
const driveId = (value) => {
  const raw = String(value || '').trim();
  const match = raw.match(/\/folders\/([^/?#]+)/) || raw.match(/[?&]id=([^&#]+)/);
  return match ? match[1] : (raw && !/^https?:/i.test(raw) ? raw : 'root');
};
const chart = (rows) => {
  if (!Array.isArray(rows) || !rows.length) return '<div class="no-data">Sem dados no período.</div>';
  const width = 860;
  const height = 245;
  const left = 42;
  const top = 18;
  const bottom = 34;
  const values = rows.map((row) => Number(row.views || 0));
  const max = Math.max(...values, 1);
  const x = (index) => left + index * (width - left - 16) / Math.max(rows.length - 1, 1);
  const y = (value) => top + (height - top - bottom) * (1 - Number(value || 0) / max);
  const points = values.map((value, index) => x(index).toFixed(1) + ',' + y(value).toFixed(1)).join(' ');
  const area = left + ',' + (height - bottom) + ' ' + points + ' ' + (width - 16) + ',' + (height - bottom);
  const step = Math.max(1, Math.ceil(rows.length / 7));
  const labels = rows.map((row, index) => (index % step === 0 || index === rows.length - 1)
    ? '<text x="' + x(index) + '" y="' + (height - 8) + '" text-anchor="middle">' + escapeHtml(dateBr(row.date).slice(0, 5)) + '</text>'
    : '').join('');
  const grid = [0, .25, .5, .75, 1].map((part) => {
    const gridY = top + part * (height - top - bottom);
    return '<line x1="' + left + '" x2="' + (width - 16) + '" y1="' + gridY + '" y2="' + gridY + '"/><text x="34" y="' + (gridY + 4) + '" text-anchor="end">' + number(max * (1 - part)) + '</text>';
  }).join('');
  return '<svg viewBox="0 0 ' + width + ' ' + height + '" xmlns="http://www.w3.org/2000/svg"><g class="grid">' + grid + '</g><polygon class="area" points="' + area + '"/><polyline class="line" points="' + points + '"/>' + labels + '</svg>';
};
const rows = (items, label, extra) => {
  const list = Array.isArray(items) ? items.slice(0, 10) : [];
  if (!list.length) return '<tr><td colspan="3" class="muted">Sem dados no período.</td></tr>';
  return list.map((item, index) => '<tr><td><span class="rank">' + (index + 1) + '</span><strong>' + escapeHtml(item[label] || item.label || 'Não identificado') + '</strong>' + (extra && item[extra] ? '<small>' + escapeHtml(item[extra]) + '</small>' : '') + '</td><td>' + number(item.views) + '</td><td>' + percent(item.percentage || 0) + '</td></tr>').join('');
};

return $input.all().map((item, index) => {
  const context = item.json.data || item.json;
  const delivery = context.delivery || {};
  const client = context.client || {};
  const data = context.report_data || {};
  const summary = data.summary || {};
  const pages = data.pages || [];
  const cities = data.cities || [];
  const states = data.states || [];
  const sources = data.sources || [];
  const devices = data.devices || [];
  const start = delivery.start_date || data.period?.start_date || '';
  const end = delivery.end_date || data.period?.end_date || '';
  const startDate = new Date(start + 'T12:00:00Z');
  const endDate = new Date(end + 'T12:00:00Z');
  const isFullMonth = startDate.getUTCDate() === 1
    && new Date(Date.UTC(endDate.getUTCFullYear(), endDate.getUTCMonth() + 1, 0)).toISOString().slice(0, 10) === end;
  const periodLabel = isFullMonth
    ? startDate.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric', timeZone: 'UTC' })
    : dateBr(start) + ' a ' + dateBr(end);
  const reportTitle = periodLabel.charAt(0).toUpperCase() + periodLabel.slice(1);
  const clientLogo = /^https?:\/\//i.test(String(client.logo_url || ''))
    ? '<img class="client-logo" src="' + escapeHtml(client.logo_url) + '">'
    : '';
  const topPage = summary.top_page || pages[0] || {};
  const topCity = summary.top_city || cities[0] || {};
  const deviceBars = (Array.isArray(devices) ? devices : []).map((device) =>
    '<div><div class="bar-head"><strong>' + escapeHtml(device.device || device.label || 'Outros') + '</strong><span>'
    + number(device.views) + ' · ' + percent(device.percentage || 0)
    + '</span></div><div class="track"><span style="width:'
    + Math.max(0, Math.min(100, Number(device.percentage || 0)))
    + '%"></span></div></div>'
  ).join('') || '<div class="muted">Sem dados no período.</div>';

  const html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><style>
@page{size:A4 portrait;margin:10mm}*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:#17324a;background:#fff;font-size:12px}.page{min-height:273mm;position:relative;padding:4px 2px 26px;page-break-after:always}.page:last-child{page-break-after:auto}.header{display:flex;align-items:center;justify-content:space-between;padding:22px 26px;border-radius:18px;background:linear-gradient(125deg,#123b5f,#2d78a8);color:#fff}.header img{max-width:170px;max-height:54px;object-fit:contain}.client-logo{padding:6px;background:#fff;border-radius:9px}.title{text-align:right}.title h1{margin:0;font-size:27px}.title p{margin:7px 0 0;opacity:.9}.client-name{margin-top:11px!important;font-size:18px;font-weight:700}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.kpi{padding:16px 14px;border:1px solid #dfe8ef;border-radius:13px;background:#f7fafc}.kpi small{display:block;color:#6f8293;font-weight:700;margin-bottom:8px}.kpi strong{display:block;font-size:26px;color:#123b5f}.section{margin-top:16px;padding:17px;border:1px solid #dfe8ef;border-radius:15px}.section h2{margin:0 0 12px;font-size:18px;color:#123b5f}.chart svg{width:100%;height:245px}.grid line{stroke:#e1e8ee;stroke-width:1}.grid text,svg>text{fill:#76899a;font-size:10px}.area{fill:rgba(55,139,190,.14)}.line{fill:none;stroke:#378bbe;stroke-width:4;stroke-linecap:round;stroke-linejoin:round}.split{display:grid;grid-template-columns:1fr 1fr;gap:14px}.table{width:100%;border-collapse:collapse}.table th{text-align:left;color:#718395;font-size:10px;text-transform:uppercase;border-bottom:2px solid #dfe8ef;padding:8px}.table td{padding:10px 8px;border-bottom:1px solid #e8eef2;vertical-align:top}.table td:nth-child(2),.table td:nth-child(3){text-align:right;font-weight:700}.table small{display:block;color:#7c8c9b;margin-top:3px}.rank{display:inline-grid;place-items:center;width:21px;height:21px;margin-right:7px;border-radius:7px;background:#e5f1f8;color:#246a95;font-weight:700}.bars{display:grid;gap:12px}.bar-head{display:flex;justify-content:space-between;margin-bottom:5px}.track{height:9px;border-radius:10px;background:#e8eef2;overflow:hidden}.track span{display:block;height:100%;border-radius:10px;background:linear-gradient(90deg,#123b5f,#47a3d4)}.insight{display:flex;gap:14px;align-items:center;padding:16px;background:#edf6fb;border-radius:14px}.insight strong{display:block;font-size:16px}.insight span{display:block;color:#65798b;margin-top:5px}.footer{position:absolute;left:4px;right:4px;bottom:4px;display:flex;justify-content:space-between;padding-top:8px;border-top:1px solid #dfe8ef;color:#8291a0;font-size:9px}.muted{color:#7c8c9b;text-align:center}.no-data{height:220px;display:grid;place-items:center;color:#718395;background:#f7fafc;border-radius:12px}
</style></head><body>
<section class="page"><header class="header"><div><img src="https://lememarketingmedico.com.br/wp-content/uploads/2025/09/Logo-Leme-Horizontal-Completa-scaled.png">${clientLogo}</div><div class="title"><h1>Relatório de Analytics do Site</h1><p>${escapeHtml(reportTitle)}</p><p class="client-name">${escapeHtml(client.nome_cliente || 'Cliente')}</p></div></header>
<div class="kpis"><div class="kpi"><small>Visualizações</small><strong>${number(summary.views)}</strong></div><div class="kpi"><small>Visitantes estimados</small><strong>${number(summary.visitors)}</strong></div><div class="kpi"><small>Média diária</small><strong>${number(summary.daily_average)}</strong></div><div class="kpi"><small>Variação</small><strong>${Number(summary.change_percent || 0) > 0 ? '+' : ''}${percent(summary.change_percent)}</strong></div></div>
<div class="split"><div class="insight"><div><small>Página mais acessada</small><strong>${escapeHtml(topPage.title || topPage.page_title || topPage.path || 'Sem dados')}</strong><span>${number(topPage.views)} visualizações</span></div></div><div class="insight"><div><small>Principal cidade</small><strong>${escapeHtml([topCity.city, topCity.state].filter(Boolean).join(' - ') || 'Não identificada')}</strong><span>${percent(topCity.percentage || 0)} dos acessos</span></div></div></div>
<div class="section chart"><h2>Evolução das visualizações</h2>${chart(data.timeline || [])}</div><footer class="footer"><span>Fonte: LEME Analytics · dados coletados no próprio site</span><span>${escapeHtml(client.site_url || '')}</span></footer></section>
<section class="page"><header class="header"><div><img src="https://lememarketingmedico.com.br/wp-content/uploads/2025/09/Logo-Leme-Horizontal-Completa-scaled.png"></div><div class="title"><h1>Páginas e cidades</h1><p>${escapeHtml(reportTitle)} · ${escapeHtml(client.nome_cliente || '')}</p></div></header>
<div class="section"><h2>Páginas mais acessadas</h2><table class="table"><thead><tr><th>Página</th><th>Views</th><th>Participação</th></tr></thead><tbody>${rows(pages, 'title', 'path')}</tbody></table></div>
<div class="section"><h2>Principais cidades</h2><table class="table"><thead><tr><th>Cidade</th><th>Views</th><th>Participação</th></tr></thead><tbody>${rows(cities, 'city', 'state')}</tbody></table></div><footer class="footer"><span>LEME Marketing Médico</span><span>Relatório de Analytics do Site</span></footer></section>
<section class="page"><header class="header"><div><img src="https://lememarketingmedico.com.br/wp-content/uploads/2025/09/Logo-Leme-Horizontal-Completa-scaled.png"></div><div class="title"><h1>Perfil dos acessos</h1><p>${escapeHtml(reportTitle)} · ${escapeHtml(client.nome_cliente || '')}</p></div></header>
<div class="split"><div class="section"><h2>Estados</h2><table class="table"><tbody>${rows(states, 'state')}</tbody></table></div><div class="section"><h2>Origens</h2><table class="table"><tbody>${rows(sources, 'source')}</tbody></table></div></div>
<div class="section"><h2>Dispositivos</h2><div class="bars">${deviceBars}</div></div>
<div class="section"><h2>Leitura do período</h2><p>O site recebeu <strong>${number(summary.views)} visualizações</strong>, realizadas por aproximadamente <strong>${number(summary.visitors)} visitantes</strong>. A página de maior interesse foi <strong>${escapeHtml(topPage.title || topPage.page_title || topPage.path || 'não identificada')}</strong> e a principal localização foi <strong>${escapeHtml([topCity.city, topCity.state].filter(Boolean).join(' - ') || 'não identificada')}</strong>.</p></div><footer class="footer"><span>Documento gerado automaticamente pelo Sistema LEME</span><span>${new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })}</span></footer></section>
</body></html>`;
  const fileName = 'relatorio-site-' + slug(client.nome_cliente) + '-' + start + '-a-' + end + '.pdf';
  const caption = '📊 *Relatório de Analytics — ' + reportTitle + '*\n\nOlá! Segue o relatório de desempenho do site de *'
    + String(client.nome_cliente || 'cliente') + '*.\n\nVisualizações: ' + number(summary.views)
    + '\nVisitantes estimados: ' + number(summary.visitors) + '\n\nLEME Marketing Médico';

  return {
    json: {
      html,
      delivery_id: String(delivery.id || ''),
      client_id: String(client.id || ''),
      file_name: fileName,
      drive_folder_id: driveId(client.drive_folder_id),
      caption,
      period_label: reportTitle
    },
    pairedItem: { item: index }
  };
});

let prepared = [];
let contexts = [];
try { prepared = $('Preparar contexto').all(); } catch (error) {}
try { contexts = $('Buscar contexto').all(); } catch (error) {}
return $input.all().map((item, index) => {
  const input = item.json || {};
  const pair = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const sourceIndex = Number.isInteger(pair?.item) ? pair.item : index;
  const deliveryId = String(prepared[sourceIndex]?.json?.delivery_id || contexts[sourceIndex]?.json?.delivery?.id || '');
  const detail = input.error?.message || input.message || input.description || 'Não foi possível consultar os dados do relatório no Sistema LEME.';
  return { json: { delivery_id: deliveryId, status: 'failed', error_code: 'context_failed', error_message: String(detail).slice(0, 900), n8n_execution_id: String($execution.id) }, pairedItem: { item: index } };
});

